/**
 * nix408: AI bot scaffolding for AI Rich replies.
 *
 * A `richResponseMessage` is only accepted when it arrives inside a `botForwardedMessage` and
 * carries a valid `botMetadata` block. Every field below is part of that handshake and must not be
 * changed per message:
 *
 *   - `botJid`        identifies the AI bot the reply is attributed to.
 *   - `proofs[]`      carries the signature and certificate chain that verify the bot.
 *   - `contextInfo`   marks the reply as forwarded from an AI bot.
 *
 * The signature and certificate chain are fixed values (verified in production for a long time),
 * so they live here once instead of being regenerated or pasted into every call.
 *
 * You do not normally import this file directly — `sendMessage({ aiRichHtml })`,
 * `prepareAiRichHtml()` and friends use it for you.
 */

/** The AI bot the reply is attributed to. Fixed. */
export const AI_BOT_JID = '867051314767696@bot';

/** Fixed signature for `verificationMetadata.proofs[0].signature` (base64). */
export const AI_BOT_SIGNATURE_B64 =
    'TklYRUwuTWVzc2FnZUJ1aWxkZXJWNC43LVZlcmlmaWNhdGlvblNpZ25hdHVyZS5NZXRhZGF0YeN55YRyad2+ZA==';

/** Fixed certificate chain for `verificationMetadata.proofs[0].certificateChain` (base64, in order). */
export const AI_BOT_CERTIFICATE_CHAIN_B64 = [
    '',
    ''
];

const b64ToBytes = (b64) => Uint8Array.from(Buffer.from(b64, 'base64'));

/** Decoded signature, ready for the proto field. */
export const AI_BOT_SIGNATURE = b64ToBytes(AI_BOT_SIGNATURE_B64);

/** Decoded certificate chain, ready for the proto field. */
export const AI_BOT_CERTIFICATE_CHAIN = AI_BOT_CERTIFICATE_CHAIN_B64.map(b64ToBytes);

/** `botMetadata.verificationMetadata` — drop this straight into the message context. */
export const AI_BOT_VERIFICATION_METADATA = {
    proofs: [
        {
            version: 1,
            useCase: 1,
            signature: AI_BOT_SIGNATURE,
            certificateChain: AI_BOT_CERTIFICATE_CHAIN
        }
    ]
};

/** `botMetadata` — the block WhatsApp checks before it renders an AI reply. */
export const AI_BOT_METADATA = {
    verificationMetadata: AI_BOT_VERIFICATION_METADATA
};

/** `messageContextInfo` — wraps the bot metadata. */
export const AI_BOT_MESSAGE_CONTEXT_INFO = {
    botMetadata: AI_BOT_METADATA
};

/** `contextInfo` — marks the reply as forwarded from an AI bot. */
export const AI_BOT_FORWARDED_CONTEXT_INFO = {
    isForwarded: true,
    forwardingScore: 1,
    forwardedAiBotMessageInfo: { botJid: AI_BOT_JID },
    forwardOrigin: 4
};
